pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory tos, uint[] memory amounts) public {
        vm.assume(tos.length == amounts.length && tos.length > 0);
        // Ensure every to address is different and not from
        for (uint i = 0; i < tos.length; i++) {
            vm.assume(tos[i] != from);
            for (uint j = i+1; j < tos.length; j++) {
                vm.assume(tos[i] != tos[j]);
            }
        }
        // Get initial balances for from and all tos plus caddress
        uint initialBalanceFrom = from.balance;
        uint initialBalanceCaddress = caddress.balance;
        uint[] memory initialBalancesTo = new uint[](tos.length);
        for (uint i = 0; i < tos.length; i++) {
            initialBalancesTo[i] = tos[i].balance;
        }

        // Attempt transfer, catch revert
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.transfer.selector, from, caddress, tos, amounts));

        if (success) {
            uint totalBefore = initialBalanceFrom + initialBalanceCaddress;
            for (uint i = 0; i < tos.length; i++) {
                totalBefore += initialBalancesTo[i];
            }
            uint totalAfter = from.balance + caddress.balance;
            for (uint i = 0; i < tos.length; i++) {
                totalAfter += tos[i].balance;
            }
            assertTrue(totalAfter >= totalBefore);
        }
    }
}

