        // Mint tokens to from so transferFrom has enough balance
        token.mint(from, 1e18);
        // Approve the contract C to spend from's tokens
        vm.prank(from);
        token.approve(address(c), type(uint).max);

        // Prepare the call by replacing caddress with the token address
        // We need to call c.transfer(from, address(token), _tos, v)
        bool result = c.transfer(from, address(token), _tos, v);
        // The reference always returns true when all calls succeed
        assertTrue(result);
    }
