        // For simplicity, we use a hardcoded address that always reverts
        vm.assume(caddress != address(0));
        vm.assume(caddress != address(c));
        // Deploy a mock token that always reverts for transferFrom
        address token = address(new MockToken());
        // Call transfer with the mock token; the reference should revert (so we catch it)
        // But we want a call that does not revert in both versions. The buggy version won't revert because it uses transfer selector which also reverts.
        // Actually both will revert if the token reverts. We need a token that succeeds for transfer but fails for transferFrom.
        // Let's deploy a token that succeeds for transfer (with any arguments) and reverts for transferFrom.
        address goodToken = address(new GoodToken());
        // However, the reference C calls transferFrom, which reverts -> C reverts, but mutant calls transfer -> succeeds.
        // We need to catch the revert on C but mutant returns true. So we use try/catch
        bool refReverted = false;
        try this.callTransfer(c, from, goodToken, _tos, v) returns (bool ret) {
            // C completed without revert, check return value
        } catch {
            refReverted = true;
